/// Upstream interface `MathUtil` (all static).
pub mod math_util {
    use super::{Mat4, Vec2};
    use crate::util::clamp_f32;

    /// Upstream `interpolateDayNightFactor(time, riseStart, riseEnd, setStart, setEnd)`.
    pub fn interpolate_day_night_factor(
        time: f32,
        rise_start: f32,
        rise_end: f32,
        set_start: f32,
        set_end: f32,
    ) -> f32 {
        if time <= 6000.0 || time > 18000.0 {
            // sunrise time
            let time = if time > 18000.0 { time - 24000.0 } else { time };
            smoothstep(time, rise_start, rise_end)
        } else {
            // sunset time
            1.0 - smoothstep(time, set_start, set_end)
        }
    }

    /// Upstream `mapTimeOfDay(time, riseStart, riseEnd, setStart, setEnd)`,
    /// with the default rise/set bounds from the shader preset baked into the
    /// map targets exactly as upstream writes them (-785, 1163, 10837, 12785).
    pub fn map_time_of_day(
        mut time: f32,
        rise_start: f32,
        rise_end: f32,
        set_start: f32,
        set_end: f32,
    ) -> f32 {
        if time <= 6000.0 || time > 18000.0 {
            // sunrise time
            if time > 18000.0 {
                time -= 24000.0;
            }
            if time < rise_start {
                time = map(time, -6000.0, rise_start, -6000.0, -785.0);
            } else if time > rise_end {
                time = map(time, rise_end, 6000.0, 1163.0, 6000.0);
            } else {
                time = map(time, rise_start, rise_end, -785.0, 1163.0);
            }
        } else {
            // sunset time
            if time < set_start {
                time = map(time, 6000.0, set_start, 6000.0, 10837.0);
            } else if time > set_end {
                time = map(time, set_end, 18000.0, 12785.0, 18000.0);
            } else {
                time = map(time, set_start, set_end, 10837.0, 12785.0);
            }
        }
        time
    }

    /// Upstream `map(x, fromMin, fromMax, toMin, toMax)`.
    pub fn map(x: f32, from_min: f32, from_max: f32, to_min: f32, to_max: f32) -> f32 {
        let f = (x - from_min) / (from_max - from_min);
        f * (to_max - to_min) + to_min
    }

    /// Upstream `smoothstep(x, e0, e1)` (Mth.clamp over the normalized span).
    pub fn smoothstep(x: f32, e0: f32, e1: f32) -> f32 {
        let x = clamp_f32((x - e0) / (e1 - e0), 0.0, 1.0);
        x * x * (3.0 - 2.0 * x)
    }

    /// Upstream `calculateClippingPlanes(Matrix4d projInverseMatrix)`.
    pub fn calculate_clipping_planes(proj_inverse_matrix: &Mat4) -> Vec2 {
        // "Fast" computation of the near and far plane doesn't work because of
        // nausea and view bobbing. This is slightly slower but should always
        // give the correct results.
        let far_plane = proj_inverse_matrix.transform(0.0, 0.0, 1.0, 1.0);
        let near_plane = proj_inverse_matrix.transform(0.0, 0.0, -1.0, 1.0);
        Vec2 {
            x: -near_plane.2 / near_plane.3,
            y: -far_plane.2 / far_plane.3,
        }
    }
}

/// Upstream `net.minecraft.util.Mth.clamp` (the seam the port touches).
pub fn clamp(v: i64, min: i64, max: i64) -> i64 {
    v.max(min).min(max)
}

/// Upstream `Mth.clamp(float, float, float)`.
pub fn clamp_f32(v: f32, min: f32, max: f32) -> f32 {
    v.max(min).min(max)
}

/// Upstream record `Tuple<A, B>`.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub struct Tuple<A, B>(pub A, pub B);

/// Upstream `org.joml.Vector2d` return shape used by MathUtil.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct Vec2 {
    pub x: f32,
    pub y: f32,
}

/// Upstream `net.minecraft.util.Mth.lerp(delta, start, end)`.
pub fn lerp_f32(delta: f32, start: f32, end: f32) -> f32 {
    start + delta * (end - start)
}

