pub const DEG_TO_RAD: f32 = std::f32::consts::PI / 180.0;

pub mod data_directory_migration {
    //! Upstream `util/DataDirectoryMigration.java`: moves the old mod data
    //! directory into the new one. `ModLoader.getGameDir()` resolves through the
    //! `loader_seam` module (engine-integration stage); file semantics mirror
    //! commons-io `FileUtils` (move-into-directory, delete-quietly).
    //!
    //! This Source Code Form is subject to the terms of the Mozilla Public
    //! License, v. 2.0. If a copy of the MPL was not distributed with this
    //! file, You can obtain one at https://mozilla.org/MPL/2.0/.
    //! Rust translation by sparticle, upstream by Qendolin.

    use std::fs;
    use std::io;
    use std::path::{Path, PathBuf};
    use std::sync::OnceLock;

    /// Upstream `ModLoader.getGameDir()` seam.
    pub mod loader_seam {
        use std::path::PathBuf;
        use std::sync::OnceLock;

        static GAME_DIR: OnceLock<PathBuf> = OnceLock::new();

        /// Engine seam: install the game directory.
        pub fn register_game_dir(dir: PathBuf) {
            let _ = GAME_DIR.set(dir);
        }

        pub fn game_dir() -> PathBuf {
            GAME_DIR.get().cloned().unwrap_or_else(|| PathBuf::from("."))
        }
    }

    /// Upstream `FileUtils.moveToDirectory(File src, File destDir, boolean
    /// createDestDir)`: moves a file or directory into `dest_dir` (never created
    /// here; `run_migration` made it first).
    fn move_to_directory(src: &Path, dest_dir: &Path) -> io::Result<()> {
        let name = src
            .file_name()
            .ok_or_else(|| io::Error::new(io::ErrorKind::InvalidInput, "no file name"))?;
        let target = dest_dir.join(name);
        match fs::rename(src, &target) {
            Ok(()) => Ok(()),
            // Same-device rename failure falls back to copy + delete, which is
            // what commons-io does across mount points.
            Err(_) => {
                if src.is_dir() {
                    copy_dir_recursive(src, &target)?;
                    fs::remove_dir_all(src)
                } else {
                    fs::copy(src, &target)?;
                    fs::remove_file(src)
                }
            }
        }
    }

    fn copy_dir_recursive(src: &Path, dst: &Path) -> io::Result<()> {
        fs::create_dir_all(dst)?;
        for entry in fs::read_dir(src)? {
            let entry = entry?;
            let ty = entry.file_type()?;
            let to = dst.join(entry.file_name());
            if ty.is_dir() {
                copy_dir_recursive(&entry.path(), &to)?;
            } else {
                fs::copy(entry.path(), &to)?;
            }
        }
        Ok(())
    }

    /// Upstream `FileUtils.deleteQuietly(File)`: never reports failure.
    fn delete_quietly(dir: &Path) {
        let _ = fs::remove_dir_all(dir);
    }

    /// Upstream `DataDirectoryMigration.runMigration()`.
    pub fn run_migration() {
        let old_dir = loader_seam::game_dir().join("better-clouds");
        if !old_dir.exists() || !old_dir.is_dir() {
            return;
        }

        let new_dir = crate::better_clouds_static::data_directory();
        if new_dir.exists() {
            return;
        }

        let _ = fs::create_dir_all(&new_dir); // newDir.mkdirs()
        let Ok(entries) = fs::read_dir(&old_dir) else {
            return; // entries == null
        };

        crate::util::log_seam::named("betterclouds").info(
            "Migrating old data directory 'better-clouds' to new directory 'data/betterclouds'",
        );

        let mut any_error = false;
        for entry in entries.flatten() {
            if move_to_directory(&entry.path(), &new_dir).is_err() {
                any_error = true; // catch (IOException ignored)
            }
        }

        if !any_error {
            delete_quietly(&old_dir);
        } else {
            crate::util::log_seam::named("betterclouds")
                .info("Some files could not be moved, keeping old directory");
        }
    }
}

