    //! Rust translation by sparticle, upstream by Qendolin.

    use crate::better_clouds_static::{
        is_initialized, is_initialized_early, logger, set_initialized,
        set_initialized_early, set_logger_name, set_version, Commands, IS_CLIENT, IS_DEV, MODID,
    };
    use crate::compat::{dh_compat, iris_compat, serene_seasons_compat, voxy_compat};
    use crate::config_seams_state;
    use crate::generator::random_path;
    use crate::gui::yacl_seam::{config_manager_handler, Component, ConfigHandlerHandle};
    use crate::platform::event_hooks;
    use crate::platform::mod_loader;
    use crate::renderdoc::renderdoc;
