        /// Upstream `DhApi.Delayed.configs.graphics().genericRendering()
        /// .cloudRenderingEnabled().setValue(false, "Better Clouds")`.
        pub fn set_cloud_rendering_enabled(_enabled: bool, _reason: &str) {}

        /// Upstream `DhApi.Delayed.renderProxy.getDhDepthTextureGlId()`
        /// (`DhApiResult<Integer>`); a result carries the payload only on success.
        pub fn get_dh_depth_texture_gl_id() -> Option<i32> {
            None
        }

        /// Upstream `DhApi.Delayed.renderProxy.isNativeRenderer()` (whether DH is
        /// using its OpenGL renderer).
        pub fn is_native_renderer() -> bool {
            false
        }

        /// Upstream `DhApi.Delayed.renderProxy.getDepthRange()`.
        pub fn get_depth_range() -> EDhApiDepthRange {
            EDhApiDepthRange::Other
        }

        /// Upstream `BlazeDhMetaRenderer.INSTANCE.dhDepthTextureWrapper`.
        pub fn blaze_dh_depth_texture() -> Option<BlazeDhDepthTexture> {
            None
        }
