pub mod texture_wrapper {
    //! Upstream `rendering/TextureWrapper.java`: unifies Minecraft textures,
    //! OpenGL texture ids, DH texture wrappers and Voxy texture wrappers under
    //! one object providing `GpuTextureView`s and `GpuSampler`s for the Blaze3D
    //! renderer.
    //!
    //! This Source Code Form is subject to the terms of the Mozilla Public
    //! License, v. 2.0. If a copy of the MPL was not distributed with this
    //! file, You can obtain one at https://mozilla.org/MPL/2.0/.
    //! Rust translation by sparticle, upstream by Qendolin.

    use std::collections::HashMap;
    use std::sync::{Arc, Mutex, OnceLock};

    use crate::rendering::blaze3d::renderpearl::{
        self, AddressMode, FilterMode, GpuSampler, GpuTextureView, RenderPass,
    };

    struct Inner {
        name: String,
        id: i32,
        view: Option<GpuTextureView>,
        sampler: Option<GpuSampler>,
        borrowed: bool,
    }

    pub struct TextureWrapper {
        inner: Mutex<Inner>,
    }

    fn cache() -> &'static Mutex<HashMap<String, Arc<TextureWrapper>>> {
        static CACHE: OnceLock<Mutex<HashMap<String, Arc<TextureWrapper>>>> = OnceLock::new();
        CACHE.get_or_init(|| Mutex::new(HashMap::new()))
    }

    impl TextureWrapper {
        /// Upstream `fromBorrowedTexture(String name, int texId, int width, int
        /// height)` (default sampler, asBorrowed).
        pub fn from_borrowed_texture(name: &str, tex_id: i32, width: i32, height: i32) -> Arc<Self> {
            let wrap = Self::from_borrowed_texture_sampler(
                name,
                tex_id,
                width,
                height,
                Box::new(Self::default_sampler),
            );
            wrap.as_borrowed()
        }

        /// Upstream `fromBorrowedTexture(..., Producer<GpuSampler> sampler)`.
        pub fn from_borrowed_texture_sampler(
            name: &str,
            tex_id: i32,
            width: i32,
            height: i32,
            sampler: Box<dyn FnOnce() -> Option<GpuSampler>>,
        ) -> Arc<Self> {
            let wrap = Self::from(
                name,
                tex_id,
                Box::new(move || {
                    renderpearl::create_texture_view_borrowed(tex_id, width, height)
                }),
                sampler,
            );
            wrap.as_borrowed()
        }

        /// Upstream `fromMcTexture(String name, Identifier mcTextureId,
        /// Producer<GpuSampler> customSampler)`; not cached, as it does not go
        /// through `from`.
        pub fn from_mc_texture(
            name: &str,
            mc_texture_id: &str,
            custom_sampler: Option<GpuSampler>,
        ) -> Arc<Self> {
            let view = renderpearl::mc_texture_view(mc_texture_id);
            Arc::new(TextureWrapper {
                inner: Mutex::new(Inner {
                    name: name.to_string(),
                    id: 0,
                    view,
                    sampler: custom_sampler,
                    borrowed: false,
                }),
            })
            .as_borrowed()
        }

        /// Upstream `from(String name, int identifier, Producer<GpuTextureView>
        /// view, Producer<GpuSampler> sampler)`.
        pub fn from(
            name: &str,
            identifier: i32,
            view: Box<dyn FnOnce() -> Option<GpuTextureView>>,
            sampler: Box<dyn FnOnce() -> Option<GpuSampler>>,
        ) -> Arc<Self> {
            let mut view = Some(view);
            let mut sampler = Some(sampler);
            let mut cache = cache().lock().unwrap();
            let entry = cache.entry(name.to_string()).or_insert_with(|| {
                Arc::new(TextureWrapper {
                    inner: Mutex::new(Inner {
                        name: name.to_string(),
                        id: identifier,
                        view: view.take().and_then(|p| p()),
                        sampler: sampler.take().and_then(|p| p()),
                        borrowed: false,
                    }),
                })
            });
            let wrap = entry.clone();
            drop(cache);
            let mut inner = wrap.inner.lock().unwrap();
            if inner.id != identifier {
                // upstream close() then re-produce view and sampler
                inner.close_view();
                inner.id = identifier;
                inner.view = view.take().and_then(|p| p());
                inner.sampler = sampler.take().and_then(|p| p());
                inner.borrowed = false;
            }
            drop(inner);
            wrap
        }

        /// Upstream `get(String name)`.
        pub fn get(name: &str) -> Option<Arc<Self>> {
            cache().lock().unwrap().get(name).cloned()
        }

        /// Upstream `closeAllWrappers()`.
        pub fn close_all_wrappers() {
            let mut cache = cache().lock().unwrap();
            for wrap in cache.values() {
                wrap.close();
            }
            cache.clear();
        }

        /// Upstream `defaultSampler()`.
        pub fn default_sampler() -> Option<GpuSampler> {
            Self::custom_sampler(AddressMode::ClampToEdge, AddressMode::ClampToEdge, FilterMode::Nearest)
        }

        /// Upstream `customSampler(AddressMode u, AddressMode v, FilterMode fm)`.
        pub fn custom_sampler(
            u: AddressMode,
            v: AddressMode,
            fm: FilterMode,
        ) -> Option<GpuSampler> {
            renderpearl::get_sampler(u, v, fm, fm, false)
        }

        /// Upstream `close()`: don't close cache-owned sampler.
        pub fn close(&self) {
            let inner = self.inner.lock().unwrap();
            inner.close_view();
        }

        /// Upstream `bindTo(RenderPass pass)`.
        pub fn bind_to(&self, pass: &mut RenderPass) {
            let inner = self.inner.lock().unwrap();
            pass.set_uniform(&inner.name, inner.view, inner.sampler);
        }

        pub fn view(&self) -> Option<GpuTextureView> {
            self.inner.lock().unwrap().view
        }

        pub fn sampler(&self) -> Option<GpuSampler> {
            self.inner.lock().unwrap().sampler
        }

        /// Upstream `asBorrowed()` (returns this).
        pub fn as_borrowed(self: &Arc<Self>) -> Arc<Self> {
            self.inner.lock().unwrap().borrowed = true;
            self.clone()
        }
    }

    impl Inner {
        fn close_view(&self) {
            if self.view.is_some() && !self.borrowed {
                // upstream view.close(); the engine seam owns the real handle
            }
        }
    }
}

