    /// Vulkan encoder mixin is excluded everywhere else.
    pub fn optional_mixin_plugin_should_apply_mixin(_target_class_name: &str, mixin_class_name: &str) -> bool {
        if mixin_class_name.ends_with("ExtendedShaderAccessor")
            || mixin_class_name.ends_with("FallbackShaderAccessor")
            || mixin_class_name.ends_with("GlCommandEncoderMixin")
        {
            return ModLoaded::IRIS;
        }
        !mixin_class_name.ends_with("VulkanCommandEncoderMixin")
    }

    /// Upstream `RuntimeMixinPlugin.getMixins()`:
    /// null outside a client environment, otherwise the runtime mixin list.
    pub fn runtime_mixin_plugin_get_mixins() -> Option<Vec<String>> {
        if !crate::compat::mod_loaded::is_client_environment() {
            return None;
        }

        let mut classes: Vec<String> = Vec::new();

        classes.push("SimpleOptionAccessor".to_string());

        classes.push("yacl.OptionListGroupSeparatorEntryMixin".to_string());
        classes.push("yacl.OptionListOptionEntryMixin".to_string());

        if classes.is_empty() {
            return None;
        }

        Some(classes)
    }
