    // ---------------------------------------------------------------------------

    /// Upstream `GameRendererMixin.iris$renderLevel`: the WrapOperation around
    /// `LevelRenderer.render(...)` inside `GameRenderer.renderLevel`, capturing
    /// the view rotation and projection matrices before delegating to the
    /// original call.
    pub fn iris_render_level<R>(
        camera_state: &CameraRenderState,
        projection_matrix: Mat4f,
        original: impl FnOnce() -> R,
    ) -> R {
        instance().with(|c| {
            c.capture_matrices(
                camera_state.view_rotation_matrix.clone(),
                projection_matrix.clone(),
            )
        });
        original()
    }

    // ---------------------------------------------------------------------------
    // required/WorldRendererMixin.java (priority 900: runs after DH)
    // ---------------------------------------------------------------------------

    struct WorldRendererMixinState {
        /// Upstream `betterclouds$replaceClouds`.
        replace_clouds: bool,
        /// Upstream `betterclouds$renderClouds` (Consumer<RenderPass>); invoked
        /// once with the pass the level renderer hands over, or None after the
        /// transparent stage.
        render_clouds: Option<Box<dyn for<'a> FnOnce(Option<&'a mut RenderPass>) + Send>>,
        /// Upstream `betterclouds$lastCameraPos`.
        last_camera_pos: Option<crate::minecraft_seam::Vec3>,
    }

    fn wr_state() -> &'static Mutex<WorldRendererMixinState> {
        static CELL: OnceLock<Mutex<WorldRendererMixinState>> = OnceLock::new();
        CELL.get_or_init(|| {
            Mutex::new(WorldRendererMixinState {
                replace_clouds: false,
                render_clouds: None,
                last_camera_pos: None,
            })
        })
    }

    /// Upstream `WorldRendererMixin.captureFrustumAndCheckState`: injected at the
    /// HEAD of `LevelRenderer.render`. `optionsRenderState` is the shadowed
    /// `LevelRenderer#optionsRenderState` field.
    pub fn capture_frustum_and_check_state(
        camera_state: &CameraRenderState,
        options_render_state: &OptionsRenderState,
    ) {
        {
            let mut s = wr_state().lock().unwrap();
            s.replace_clouds = false;
            s.render_clouds = None;
        }
        instance().with(|c| {
            c.capture_frustum(camera_state.clone());
            c.check_state(options_render_state);
        });
    }

    /// Upstream `WorldRendererMixin.prepareClouds`: injected before
    /// `FrameGraphBuilder.execute` inside `LevelRenderer.render`.
    pub fn prepare_clouds(camera: &CameraRenderState, options_render_state: &OptionsRenderState) {
        if options_render_state.cloud_status != CloudStatus::Off {
            let mut s = wr_state().lock().unwrap();
            s.last_camera_pos = Some(camera.pos);
            // Upstream passes `render -> betterclouds$renderClouds = render` as the
            // scheduleRender consumer: the assignment callback. The coordinator
            // stores the scheduled render body itself, so the stored consumer
            // forwards the pass handed over by the level renderer.
            let scheduled = std::cell::Cell::new(false);
            instance().with(|c| {
                c.render_clouds(
                    &mut || scheduled.set(true),
                    camera.pos,
                    camera.camera_entity_partial_ticks,
                );
            });
            if scheduled.get() {
                s.render_clouds = Some(Box::new(|pass| {
                    instance().with(|c| c.render_scheduled(pass));
                }));
            }
        }
    }

    /// Upstream `WorldRendererMixin.renderCloudsBeforeTransparent`: injected at
    /// the TAIL of `LevelRenderer.executeSolid` (after opaque, before
    /// transparency; only runs when the camera is below the cloud level).
    /// `frontend_render_pass_open` stands in for upstream's
    /// `renderPass instanceof FrontendRenderPass && !((FrontendRenderPassAccessor)
    /// renderPass).isClosed()` check; the carrier wiring supplies it.
    pub fn render_clouds_before_transparent(
        _chunk_sections_to_render: (),
        _feature_frame: (),
        render_pass: Option<&mut RenderPass>,
        frontend_render_pass_open: bool,
    ) {
        let consumer = {
            let mut s = wr_state().lock().unwrap();
            let consumer = s.render_clouds.take();
            let last = s.last_camera_pos;
            (consumer, last)
        };
        let (consumer, last_camera_pos) = consumer;
        let Some(consumer) = consumer else { return };
        let Some(last_camera_pos) = last_camera_pos else { return };

        let cloud_height = instance().with(|c| {
            c.renderer
                .as_mut()
                .map(|r| r.get_cloud_height())
        });
        // Upstream: lastCameraPos.y > (r != null ? r.getCloudHeight() : Integer.MAX_VALUE)
        let limit = match cloud_height {
            Some(h) => h as f64,
            None => 2147483647.0f64,
        };
        if last_camera_pos.y > limit {
            return;
        }

        let pass = match render_pass {
            Some(p) if frontend_render_pass_open => Some(p),
            _ => None,
        };
        consumer(pass);
    }

    /// Upstream `WorldRendererMixin.renderCloudsAfterTransparent`: injected at the
    /// HEAD of `LevelRenderer.executeOutline` (after transparency, before debug;
    /// only runs when the camera is above the cloud level).
    pub fn render_clouds_after_transparent() {
        let consumer = wr_state().lock().unwrap().render_clouds.take();
        if let Some(consumer) = consumer {
            consumer(None);
        }
    }

