    /// Upstream `ConfigGUI.createOption(Class<T> ignoredTypeClass, String key,
    /// boolean hasDescription)`.
    pub fn create_option_desc<T: Clone + Send + 'static>(
        key: &str,
        has_description: bool,
    ) -> YACL36OptionBuilderImpl<T> {
        let mut builder =
            yacl_option_builder_create::<T>(Box::new(PlainOptionBuilderDelegate::default()));
        // Upstream `.name(optionLabel(key))`.
        YACLOptionBuilder::name(&mut builder, option_label(key));
        // Upstream `.instant(false)`.
        YACLOptionBuilder::instant(&mut builder, false);
        // Upstream `.listener((opt, _) -> opt.applyValue())`.
        YACLOptionBuilder::listener(
            &mut builder,
            Box::new(|opt: &OptionHandleT<T>, _: &T| {
                // Upstream `opt.applyValue()`.
                opt.apply_value();
            }),
        );
        if has_description {
            YACLOptionBuilder::description(
                &mut builder,
                OptionDescriptionHandle::of_single(option_description(key)),
            );
        }
        builder
    }

