    /// Upstream `String.format("%,.2f", value)`'s locale grouping separator.
    fn format_with_thousands(value: f32) -> String {
        let raw = format!("{:.2}", value);
        let (int_part, frac_part) = match raw.split_once('.') {
            Some((i, f)) => (i.to_string(), f.to_string()),
            None => (raw, String::new()),
        };
        let negative = int_part.starts_with('-');
        let digits = if negative {
            int_part[1..].to_string()
        } else {
            int_part
        };
        let mut grouped = String::new();
        for (i, c) in digits.chars().enumerate() {
            if i > 0 && (digits.len() - i) % 3 == 0 {
                grouped.push(',');
            }
            grouped.push(c);
        }
        if negative {
            grouped.insert(0, '-');
        }
        if frac_part.is_empty() {
            grouped
        } else {
            format!("{}.{}", grouped, frac_part)
        }
    }

    /// Upstream `ConfigGUI.formatAsTwoDecimals(Float value)`.
    pub fn format_as_two_decimals(value: f32) -> Component {
        // Upstream `Component.literal(String.format("%,.2f", value)
        //     .replaceAll("[\u00a0\u202F]", " "))`.
        let text = format_with_thousands(value)
            .replace('\u{a0}', " ")
            .replace('\u{202f}', " ");
        Component::literal(text)
    }

