    /// Upstream `config/gui/DimensionsGUI.java`: the compatibility "enabled
    /// dimensions" list option. The port keeps `DimensionKey` (the string form)
    /// as the stored value and carries the aliased `Config` through a shared
    /// cell the closures capture.
    pub struct DimensionsGUI {
        /// Upstream `public final ListOption.Builder<String> compatDimensionsListGroup`.
        pub compat_dimensions_list_group: ListOptionBuilderHandle,
        /// Upstream `private List<String> values` (the state closures keep it
        /// current; nothing else reads it on the current surface).
        #[allow(dead_code)]
        values: Arc<Mutex<Vec<String>>>,
    }

    impl DimensionsGUI {
        /// Upstream `public DimensionsGUI(Config defaults, Config config)`.
        pub fn new(defaults: &Config, config: Arc<Mutex<Config>>) -> Self {
            // Upstream `values = config.enabledDimensions.stream()
            //     .map(key -> key.identifier().toString()).toList()`; `DimensionKey`
            // is already the string form, so the port clones the keys.
            let values = Arc::new(Mutex::new(config.lock().unwrap().enabled_dimensions.clone()));
            let getter_values = values.clone();
            let setter_values = values.clone();
            let setter_config = config.clone();
            // Upstream `.state(StateManager.createInstant(
            //     defaults.enabledDimensions.stream().map(key -> key.identifier().toString()).toList(),
            //     () -> values, this::setValues))`.
            let binding = Binding::generic(
                defaults.enabled_dimensions.clone(),
                Arc::new(move || getter_values.lock().unwrap().clone()),
                Arc::new(move |new_values: &Vec<String>| {
                    *setter_values.lock().unwrap() = new_values.clone();
                    Self::set_values(&setter_config, new_values.clone());
                }),
            );
            let mut builder = ListOptionBuilderHandle(0);
            builder
                // Upstream `.name(groupLabel("compat.dimensions"))`.
                .name(group_label("compat.dimensions"))
                // Upstream `.description(OptionDescription.of(groupDescription("compat.dimensions")))`.
                .description(OptionDescriptionHandle::of_single(group_description(
                    "compat.dimensions",
                )))
                .state(state_manager_create_instant(&binding))
                // Upstream `.listener((option, _) -> option.applyValue())`.
                .listener(Box::new(|| {}))
                // Upstream `.controller(StringControllerBuilder::create)`.
                .controller(Box::new(string_controller_builder_create))
                // Upstream `.initial(BuiltinDimensionTypes.OVERWORLD.identifier().toString())`.
                .initial(OVERWORLD_IDENTIFIER.to_string());
            DimensionsGUI {
                compat_dimensions_list_group: builder,
                values,
            }
        }

        /// Upstream `private void setValues(List<String> values)` (instance
        /// method upstream; the port runs it over the shared cells).
        fn set_values(config: &Arc<Mutex<Config>>, values: Vec<String>) {
            // Upstream `values.stream()
            //     .map(value -> { if (!value.contains(":")) return null;
            //                     return Identifier.tryParse(value); })
            //     .filter(Objects::nonNull).distinct()
            //     .map(value -> ResourceKey.create(Registries.DIMENSION_TYPE, value))
            //     .toList()`.
            let mut out: Vec<String> = Vec::new();
            for value in values.iter().filter_map(|v| Identifier::try_parse(v)) {
                let key = ResourceKeyHandle::create_dimension_type(value).0;
                if !out.contains(&key) {
                    out.push(key);
                }
            }
            config.lock().unwrap().enabled_dimensions = out;
        }
    }

