            // Upstream `worldCurvatureSize = createOption(int.class, "worldCurvatureSize", true)
            //     .binding(Math.max(worldCurvatureValues.indexOf(defaults.shaderPreset().worldCurvatureSize), 0),
            //              () -> Math.max(worldCurvatureValues.indexOf(config.shaderPreset().worldCurvatureSize), 0),
            //              val -> config.shaderPreset().worldCurvatureSize = worldCurvatureValues.get(val))
            //     .customController(opt -> new IntegerSliderController(opt, 0, worldCurvatureValues.size() - 1, 1,
            //         i -> worldCurvatureValues.get(i) == 0 ? Component.translatable("options.off")
            //             : Component.literal(worldCurvatureValues.get(i).toString()))).build();`
            let world_curvature_size = {
                let values_def = world_curvature_values.clone();
                let def = values_def
                    .iter()
                    .position(|&v| v == defaults.shader_preset().world_curvature_size)
                    .map(|i| i as i32)
                    .unwrap_or(-1)
                    .max(0);
                let cfg_get = config.clone();
                let cfg_set = config.clone();
                let mut builder = create_option_desc::<i32>("worldCurvatureSize", true);
                YACLOptionBuilder::binding_generic(
                    &mut builder,
                    def,
                    Arc::new(move || {
                        let cfg = cfg_get.lock().unwrap();
                        let value = cfg.shader_preset().world_curvature_size;
                        values_def
                            .iter()
                            .position(|&v| v == value)
                            .map(|i| i as i32)
                            .unwrap_or(-1)
                            .max(0)
                    }),
                    Arc::new({
                        let values = world_curvature_values.clone();
                        move |val: &i32| {
                            // Upstream `worldCurvatureValues.get(val)` (out of range
                            // throws upstream; the port's index does the same).
                            cfg_set.lock().unwrap().shader_preset_mut().world_curvature_size =
                                values[*val as usize];
                        }
                    }),
                );
                YACLOptionBuilder::custom_controller(
                    &mut builder,
                    Box::new({
                        let values = world_curvature_values.clone();
                        move |opt: &OptionHandleT<i32>| {
                            let values = values.clone();
                            integer_slider_controller(
                                opt,
                                0,
                                values.len() as i32 - 1,
                                1,
                                Some(Box::new(move |i: i32| {
                                    let value = values[i as usize];
                                    if value == 0 {
                                        Component::translatable("options.off")
                                    } else {
                                        Component::literal(format!("{}", value))
                                    }
                                })),
                            )
                        }
                    }),
                );
                YACLOptionBuilder::build(&mut builder)
            };

            // Upstream `shaderConfigPresetOptions.addAll(List.of(presetTitle, description, saturation,
