    /// Upstream `dev.isxander.yacl3.api.Option<T>` surface.
    #[derive(Clone)]
    pub struct OptionHandleT<T> {
        pub id: u64,
        _t: std::marker::PhantomData<T>,
    }

    impl<T: Clone + 'static> OptionHandleT<T> {
        /// Upstream `Option.pendingValue()`. The registry carries the binding
        /// getter plus any `requestSet` value the engine stashed.
        pub fn pending_value(&self) -> T {
            let map = OPTION_STATES.lock().unwrap();
            if let Some(states) = map.as_ref() {
                if let Some(state) = states.get(&self.id) {
                    let requested = state.requested.lock().unwrap();
                    if let Some(value) = requested.as_ref() {
                        return value.downcast_ref::<T>().expect("option state type mismatch").clone();
                    }
                    drop(requested);
                    let value = (state.get)();
                    return *value.downcast::<T>().expect("option state type mismatch");
                }
            }
            panic!("Option.pendingValue() is a YACL engine surface");
        }

        /// Upstream `Option.applyValue()` (applies the pending value, else the
        /// binding's current value, through the binding setter).
        pub fn apply_value(&self) {
            let map = OPTION_STATES.lock().unwrap();
            if let Some(states) = map.as_ref() {
                if let Some(state) = states.get(&self.id) {
                    let Some(set) = &state.set else {
                        return;
                    };
                    let requested = state.requested.lock().unwrap().take();
                    let value = match requested {
                        Some(value) => value,
                        None => (state.get)(),
                    };
                    set(&*value);
                    return;
                }
            }
            panic!("Option.applyValue() is a YACL engine surface");
        }

        /// Upstream `Option.setAvailable(boolean)`.
        pub fn set_available(&self, available: bool) {
            let map = OPTION_STATES.lock().unwrap();
            if let Some(states) = map.as_ref() {
                if let Some(state) = states.get(&self.id) {
                    state.available.store(available, std::sync::atomic::Ordering::Relaxed);
                    return;
                }
            }
            panic!("Option.setAvailable(boolean) is a YACL engine surface");
        }

        /// Upstream `Option.forgetPendingValue()`.
        pub fn forget_pending_value(&self) {
            let map = OPTION_STATES.lock().unwrap();
            if let Some(states) = map.as_ref() {
                if let Some(state) = states.get(&self.id) {
                    state.requested.lock().unwrap().take();
                    return;
                }
            }
            panic!("Option.forgetPendingValue() is a YACL engine surface");
        }
    }

    impl<T: Clone + Send + 'static> OptionHandleT<T> {
        /// Upstream `Option.requestSet(T)` (the ported registry stashes the
        /// pending value; `applyValue` applies it).
        pub fn request_set(&self, value: T) {
            let map = OPTION_STATES.lock().unwrap();
            if let Some(states) = map.as_ref() {
                if let Some(state) = states.get(&self.id) {
                    *state.requested.lock().unwrap() = Some(Box::new(value));
                    return;
                }
            }
            panic!("Option.requestSet(T) is a YACL engine surface");
        }
    }

