    /// Upstream `dev.isxander.yacl3.gui.utils.GuiUtils.shortenString` (engine
    /// surface; trims through the port's text-width seam).
    pub fn shorten_string(text: &str, max_width: i32, ellipsis: &str) -> String {
        if text_renderer_width(&Component(text.to_string())) <= max_width {
            return text.to_string();
        }
        let mut shortened: String = text.chars().collect();
        while !shortened.is_empty()
            && text_renderer_width(&Component(format!("{}{}", shortened, ellipsis))) > max_width
        {
            shortened.pop();
        }
        format!("{}{}", shortened, ellipsis)
    }

