    /// The ported engine's per-option runtime state. Upstream the YACL engine
    /// holds it on each `Option` instance; the ported handles are opaque ids, so
    /// the state lives here, keyed by the handle id.
    pub struct OptionState {
        /// Upstream the binding getter (`Supplier<T>`).
        pub get: Box<dyn Fn() -> Box<dyn std::any::Any + Send> + Send + Sync>,
        /// Upstream the binding setter (`Consumer<T>`), `None` when the option
        /// was built without a binding.
        pub set: Option<Box<dyn Fn(&(dyn std::any::Any + Send)) + Send + Sync>>,
        /// Upstream the option's `available` flag.
        pub available: std::sync::atomic::AtomicBool,
        /// Upstream the pending value `requestSet` stashed before `applyValue`.
        pub requested: std::sync::Mutex<Option<Box<dyn std::any::Any + Send>>>,
    }

    static OPTION_STATES: std::sync::Mutex<Option<std::collections::HashMap<u64, std::sync::Arc<OptionState>>>> =
        std::sync::Mutex::new(None);

    static NEXT_OPTION_ID: std::sync::atomic::AtomicU64 = std::sync::atomic::AtomicU64::new(1);

    /// The next fresh option handle id (upstream the engine allocates one per
    /// option).
    pub fn next_option_id() -> u64 {
        NEXT_OPTION_ID.fetch_add(1, std::sync::atomic::Ordering::Relaxed)
    }

    /// Registers an option's binding state under its handle id (upstream the
    /// engine does this as part of building the option). The ported engine's
    /// option values are the `Send` primitives, `String` and `Color`.
    pub fn register_option_state<T: Clone + Send + 'static>(id: u64, binding: Option<&Binding<T>>) {
        let Some(binding) = binding else {
            return;
        };
        let Binding::Generic { getter, setter, def: _ } = binding;
        let getter = getter.clone();
        let setter = setter.clone();
        let get: Box<dyn Fn() -> Box<dyn std::any::Any + Send> + Send + Sync> =
            Box::new(move || Box::new(getter()));
        let set: Box<dyn Fn(&(dyn std::any::Any + Send)) + Send + Sync> = {
            let s = setter.clone();
            Box::new(move |v: &(dyn std::any::Any + Send)| {
                if let Some(v) = v.downcast_ref::<T>() {
                    s(v);
                }
            })
        };
        let mut guard = OPTION_STATES.lock().unwrap();
        let map = guard.get_or_insert_with(std::collections::HashMap::new);
        map.insert(
            id,
            std::sync::Arc::new(OptionState {
                get,
                set: Some(set),
                available: std::sync::atomic::AtomicBool::new(true),
                requested: std::sync::Mutex::new(None),
            }),
        );
    }

    /// The mixin-duck description state the engine reads through the owning
    /// option (upstream the mixins inject the description onto the option /
    /// controller instances; the ported handles are ids, so it lives here).
    #[derive(Default)]
    pub struct DuckDescriptionState {
        /// `betterclouds$setDescription` (a replace).
        pub set: Option<OptionDescriptionHandle>,
        /// `betterclouds$appendToDescription` (appends).
        pub appended: Vec<OptionDescriptionHandle>,
    }

    static DUCK_DESCRIPTIONS: std::sync::Mutex<Option<std::collections::HashMap<u64, DuckDescriptionState>>> =
        std::sync::Mutex::new(None);

    /// Upstream `StringControllerDuck.betterclouds$setDescription` /
    /// `OptionDuck.betterclouds$setDescription`.
    pub fn duck_description_set(id: u64, description: OptionDescriptionHandle) {
        let mut guard = DUCK_DESCRIPTIONS.lock().unwrap();
        let map = guard.get_or_insert_with(std::collections::HashMap::new);
        map.entry(id).or_default().set = Some(description);
    }

    /// Upstream `OptionDuck.betterclouds$appendToDescription`.
    pub fn duck_description_append(id: u64, description: OptionDescriptionHandle) {
        let mut guard = DUCK_DESCRIPTIONS.lock().unwrap();
        let map = guard.get_or_insert_with(std::collections::HashMap::new);
        map.entry(id).or_default().appended.push(description);
    }

