    impl Component {
        /// Upstream `Component.append(Component)`.
        pub fn append(&self, other: &Component) -> Self {
            Component(format!("{}{}", self.0, other.0))
        }

        /// Upstream `Component.withStyle(UnaryOperator<Style>)`. The ported
        /// `Component` is a flat string, so the style rides along as the leading
        /// `\u{a7}` formatting codes (what the vanilla renderer reads).
        pub fn with_style(&self, f: impl FnOnce(&mut Style) -> &mut Style) -> Self {
            let mut style = Style::default();
            f(&mut style);
            let mut codes = String::new();
            if let Some(color) = &style.color {
                codes.push_str(color.code());
            }
            if style.italic {
                codes.push_str("\u{a7}o");
            }
            if style.strikethrough {
                codes.push_str("\u{a7}m");
            }
            if style.underline {
                codes.push_str("\u{a7}n");
            }
            Component(format!("{}{}", codes, self.0))
        }
    }

