    /// Upstream `YetAnotherConfigLib.create(ConfigHandler, BiConsumer)` (the YACL
    /// build entry: runs the assemble lambda over a fresh builder, with the
    /// handler's save as the default `saveFunction`).
    pub fn yet_another_config_lib_create(
        _handler: ConfigHandlerHandle,
        assemble: impl FnOnce(&mut YetAnotherConfigLibBuilder),
    ) -> YetAnotherConfigLib {
        let mut builder = YetAnotherConfigLibBuilder::default();
        assemble(&mut builder);
        YetAnotherConfigLib {
            // Upstream the save `Runnable` is the builder's `save()` action when one
            // was registered, else the handler's save; the ported action is
            // `FnOnce` (it consumes the sub-GUIs), so the `Fn` wrapper runs it once.
            save_function: Some(match builder.save {
                Some(action) => {
                    let action = std::sync::Mutex::new(Some(action));
                    let wrapped: Box<dyn Fn() + Send> = Box::new(move || {
                        if let Some(f) = action.lock().unwrap().take() {
                            f();
                        }
                    });
                    wrapped
                }
                None => Box::new(config_manager_handler_save),
            }),
            init_consumer: builder.init_consumer,
            categories: builder.categories,
        }
    }

